/**
 * Dota 2 SkinForge — Equipment Slots Armory & Slot Definition Resolver
 *
 * Source of truth for heroes is `data/heroes_armory.json`, regenerated by `npm run armory`
 * from the game's own `items_game.txt`. Each hero owns its slots directly, and every slot
 * owns its items:
 *
 *   hero.slots[] -> { slot, title, empty_img, mods[] }
 *   mod          -> { id, name, rarity, img }
 *
 * Non-hero categories come from `data/other_armory.json`, which uses the same shape; their
 * display names come from `data/categories.json`.
 *
 * Results are memoised per tag and shared between callers, so treat them as read-only.
 */

import heroesArmoryData from '../../../data/heroes_armory.json'
import otherArmoryData from '../../../data/other_armory.json'
import categoriesData from '../../../data/categories.json'
import { getItemRarityKey, rarityRank } from '../utils/itemImages'
import type { HeroEntry } from '../env'

export interface SlotMod {
  /** Valve schema item id from `items_game.txt`. */
  id?: number
  name: string
  rarity?: string
  img?: string
}

export interface ArmorySlot {
  slot: string
  title: string
  empty_img?: string
  mods: SlotMod[]
}

export interface ArmoryVariant {
  id: string
  title: string
}

export interface HeroArmoryEntry {
  tag?: string
  variant_default?: string
  variants?: ArmoryVariant[]
  variant_slots?: Record<string, string[]>
  pbases?: boolean
  slots: ArmorySlot[]
}

/** Tags compare without case or punctuation: `anti-mage`, `Ancient Apparition`, `antimage`. */
export function normalizeTag(tag: string): string {
  return tag.toLowerCase().replace(/[^a-z0-9]/g, '')
}

const armory = (heroesArmoryData as unknown as Record<string, HeroArmoryEntry>) || {}

const armoryIndex = new Map<string, HeroArmoryEntry>()
for (const [key, entry] of Object.entries(armory)) {
  armoryIndex.set(normalizeTag(key), entry)
  if (entry?.tag) armoryIndex.set(normalizeTag(entry.tag), entry)
}

interface CategoryLabel {
  tag: string
  name: string
}

/** Category labels live in `categories.json`; this only looks them up. */
const categoryNames = new Map<string, string>(
  ((categoriesData as unknown as { categories?: CategoryLabel[] }).categories ?? []).map((category) => [category.tag, category.name])
)

export function formatHeroName(tag?: string | null): string {
  if (!tag) return ''
  const category = categoryNames.get(tag.toLowerCase())
  if (category) return category
  return tag
    .split(/[_\s-]+/)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ')
}

/** Filter out removed slots (taunt, Diretide shimmer costumes). */
function cleanSlots(entry: HeroArmoryEntry): HeroArmoryEntry {
  return {
    ...entry,
    slots: entry.slots
      .filter((s) => s.slot !== 'taunt')
      .map((s) => ({
        ...s,
        mods: s.mods.filter((m) => !m.name.toLowerCase().includes('diretide shimmer costume'))
      }))
      .filter((s) => s.mods.length > 0)
  }
}

interface OtherCategoryEntry {
  tag: string
  slots: ArmorySlot[]
}

const otherArmory = (otherArmoryData as unknown as Record<string, OtherCategoryEntry>) || {}
const otherArmoryIndex = new Map<string, OtherCategoryEntry>()
for (const [key, entry] of Object.entries(otherArmory)) {
  otherArmoryIndex.set(normalizeTag(key), entry)
  if (entry?.tag) otherArmoryIndex.set(normalizeTag(entry.tag), entry)
}

function byRarity(a: SlotMod, b: SlotMod): number {
  return rarityRank(getItemRarityKey(b)) - rarityRank(getItemRarityKey(a))
}

/**
 * Rarest item first inside every slot. The sort is stable, so items of the same rarity keep
 * their armory order — which is what keeps a style variant next to its base item.
 */
function sortModsByRarity(entry: HeroArmoryEntry): HeroArmoryEntry {
  return {
    ...entry,
    slots: entry.slots.map((slot) => ({ ...slot, mods: [...slot.mods].sort(byRarity) }))
  }
}

const prepared = new Map<string, HeroArmoryEntry | null>()

/**
 * Resolve a hero (or non-hero category) to its slot armory.
 * Returns `null` when nothing is known about the tag. The result is memoised per tag —
 * callers must not mutate it.
 */
export function getHeroSlotsDefinition(heroTag?: string | null, heroObj?: HeroEntry | null): HeroArmoryEntry | null {
  if (!heroTag) return null

  const key = normalizeTag(heroTag)
  const cached = prepared.get(key)
  if (cached !== undefined) return cached

  const entry = armoryIndex.get(key) ?? (heroObj?.tag ? armoryIndex.get(normalizeTag(heroObj.tag)) : undefined)
  const other = entry ? undefined : otherArmoryIndex.get(key)
  const resolved = entry ? sortModsByRarity(cleanSlots(entry)) : other ? sortModsByRarity(other as unknown as HeroArmoryEntry) : null

  prepared.set(key, resolved)
  return resolved
}
